const secret = pm.environment.get("totp_secret");

if (!secret) {
    throw new Error("totp_secret is not set");
}

// Base32 decode
function base32Decode(input) {
    const alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZ234567";
    input = input.replace(/[\s=]/g, "").toUpperCase();

    let bits = "";

    for (const char of input) {
        const val = alphabet.indexOf(char);

        if (val === -1) {
            throw new Error("Invalid Base32 character: " + char);
        }

        bits += val.toString(2).padStart(5, "0");
    }

    const bytes = [];

    for (let i = 0; i + 8 <= bits.length; i += 8) {
        bytes.push(parseInt(bits.substring(i, i + 8), 2));
    }

    return bytes;
}

// Convert bytes to CryptoJS WordArray
function bytesToWordArray(bytes) {
    const words = [];

    for (let i = 0; i < bytes.length; i++) {
        words[i >>> 2] |= bytes[i] << (24 - (i % 4) * 8);
    }

    return CryptoJS.lib.WordArray.create(words, bytes.length);
}

const secretBytes = base32Decode(secret);
const key = bytesToWordArray(secretBytes);

// TOTP counter = floor(unix_time / 30)
const counter = Math.floor(Date.now() / 1000 / 30);

// 8-byte big-endian counter
const counterBytes = [];

for (let i = 7; i >= 0; i--) {
    counterBytes.push(
        Math.floor(counter / Math.pow(256, i)) & 0xff
    );
}

const counterWordArray = bytesToWordArray(counterBytes);

// HMAC-SHA1
const hash = CryptoJS.HmacSHA1(
    counterWordArray,
    key
);

const hex = hash.toString(CryptoJS.enc.Hex);

// Dynamic truncation
const offset = parseInt(hex.substring(38, 40), 16) & 0x0f;

const binary =
    ((parseInt(hex.substring(offset * 2, offset * 2 + 2), 16) & 0x7f) << 24) |
    ((parseInt(hex.substring(offset * 2 + 2, offset * 2 + 4), 16)) << 16) |
    ((parseInt(hex.substring(offset * 2 + 4, offset * 2 + 6), 16)) << 8) |
    ((parseInt(hex.substring(offset * 2 + 6, offset * 2 + 8), 16)));

const totp = String(binary % 1000000).padStart(6, "0");

pm.environment.set("totp", totp);

console.log("TOTP:", totp);
console.log("Counter:", counter);
console.log("Time:", new Date().toISOString());

